node -e "
import('./proxy.ts').then(async (mod) => {
  const { NextRequest } = await import('next/server.js');
  let logged = [];
  const origLog = console.log;
  console.log = (...args) => { logged.push(args); origLog(...args); };

  const req1 = new NextRequest('http://localhost:3000/hello/world?foo=bar');
  const res1 = mod.proxy(req1);
  console.log = origLog;

  const req2 = new NextRequest('http://localhost:3000/another');
  const res2 = mod.middleware(req2);

  const id1 = res1.headers.get('X-Request-Id');
  const id2 = res2.headers.get('X-Request-Id');

  console.log('id1:', id1);
  console.log('id2:', id2);
  console.log('different:', id1 !== id2);
  console.log('logged:', logged);
});
"

